<?php declare(strict_types=1);
require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access,Db,SecretBox};
use Kulturhus\Native\Cms\{Schema,Media,MediaArchive,MediaCatalogue,MediaMetadata,MediaQuota,Pages,Conflict};
use Kulturhus\Native\Web\MediaLibrary;
$db=TestSupport::db();TestSupport::seed($db);Schema::install($db);$admin=new Access($db,'admin');$reader=new Access($db,'reader');$editor=new Access($db,'editor');$checks=0;
function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException($label);$checks++;echo 'PASS '.$label."\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException|InvalidArgumentException|Conflict){check(true,$label);return;}throw new RuntimeException($label);}
$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/media-archive';mkdir($root,0700,true);$image=imagecreatetruecolor(48,32);imagefill($image,0,0,imagecolorallocate($image,40,130,180));imagepng($image,$root.'/own.png');unset($image);
$media=new Media($db,$admin,$root.'/media');$asset=$media->upload($root.'/own.png','Eigene Originalaufnahme.png','Eigene Bildbeschreibung');$id=$asset['id'];$second=$media->upload($root.'/own.png','Weitere eigene Aufnahme.png','Zweites eigenes Bild');
$meta=new MediaMetadata($db,$admin,new SecretBox(str_repeat('a',32)));$m=$meta->save($id,['alt'=>'Eigene Beschreibung','rights_state'=>'cleared','consent_state'=>'not_required','credit'=>'Eigener Fotocredit','source_name'=>'Eigene Kamera','license_name'=>'Eigene Nutzung'],0,'Eigener unveränderter privater Nachweis');
$page=(new Pages($db,$admin))->save(['title'=>'Eigene Veröffentlichung','slug'=>'own-archive-source','body'=>'Eigener ursprünglicher Inhalt','media_ids'=>[$id]]);(new Pages($db,$admin))->publish($page['id'],$page['version']);$published=(new Pages($db,$admin))->publicPage($page['slug']);
$originals=[$db->query('SELECT * FROM khcms_media ORDER BY id')->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata ORDER BY media_id')->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata_revisions ORDER BY media_id,version')->fetchAll(),$db->query('SELECT * FROM khcms_pages ORDER BY id')->fetchAll(),$db->query('SELECT * FROM khcms_revisions ORDER BY page_id,revision')->fetchAll()];
$hashes=[];foreach(['original','large','medium','thumb']as$size)$hashes[$size]=hash_file('sha256',$media->variant($id,$size)['path']);$quota=(new MediaQuota($db,$admin))->get();$archive=new MediaArchive($db,$admin);
check($archive->get($id)['version']===0&&!$archive->get($id)['archived']&&$archive->history($id)['total']===0,'an original photo starts active with no invented archive history');
$state=$archive->save($id,true,0);check($state['archived']&&$state['version']===1,'archive creates a separate original-bound state version');
check((new MediaArchive($db,$reader))->get($id)===$state,'readers see the same exact archive state');
check($archive->history($id)['total']===1&&$archive->history($id)['rows'][0]['actor_name']===$state['actor_name'],'archive history captures its original actor name');
$historyRow=Db::run($db,'SELECT * FROM khcms_media_archive_history WHERE media_id=? AND version=1',[$id])->fetch();
$catalogue=new MediaCatalogue($db,$admin);
check($catalogue->listing(['media_archive'=>'all'])['total']===2,'all catalogue includes active and archived originals');
check($catalogue->listing(['media_archive'=>'active'])['total']===1&&$catalogue->listing(['media_archive'=>'active'])['rows'][0]['id']===$second['id'],'active catalogue separates only the exact archived original');
check($catalogue->listing(['media_archive'=>'archived'])['total']===1&&$catalogue->listing(['media_archive'=>'archived'])['rows'][0]['id']===$id,'archive catalogue returns the original photo with exact ID');
check($catalogue->listing(['media_archive'=>'archived','media_q'=>'Originalaufnahme','media_state'=>'cleared'])['total']===1,'archive filter combines safely with own filename and rights search');
check($media->publicVariant($id,'medium',$published)!==null,'original published photo remains available while archived');
check(count($media->list())===2&&$media->variant($id,'original')!==null,'archive preserves existing media references and private selection originals');
check((new MediaQuota($db,$admin))->get()===$quota,'archive retains the exact stored photo quota usage');
check($meta->get($id)===$m&&$meta->privateProof($id,1)==='Eigener unveränderter privater Nachweis','archive leaves copyright version and original encrypted proof intact');
check($archive->save($id,true,1)===$state&&$archive->history($id)['total']===1,'repeated unchanged state does not invent another archive event');
denied(fn()=>$archive->save($id,false,0),'stale archive form cannot undo another version');
denied(fn()=>(new MediaArchive($db,$reader))->save($id,false,1),'reader cannot change archival state');
denied(fn()=>(new MediaArchive($db,new Access($db,'outsider')))->get($id),'foreign club cannot inspect archive state');
denied(fn()=>(new MediaArchive($db,new Access($db,'outsider')))->save($id,false,1),'foreign club cannot write archive state');
foreach(['',str_repeat('f',32),'../own',str_repeat('a',31)]as$bad)denied(fn()=>$archive->get($bad),'invalid or missing photo cannot acquire an archive state');
foreach([0,-1,'01',[],1000001]as$bad)denied(fn()=>$archive->history($id,$bad),'malformed history page is rejected');
foreach([[],true,'deleted',' archived']as$bad)denied(fn()=>$catalogue->listing(['media_archive'=>$bad]),'malformed archive filter cannot alter catalogue scope');
$state=(new MediaArchive($db,$editor))->save($id,false,1);check(!$state['archived']&&$state['version']===2&&$archive->history($id)['total']===2,'ordinary media editor can restore the exact photo');
check(Db::run($db,'SELECT * FROM khcms_media_archive_history WHERE media_id=? AND version=1',[$id])->fetch()===$historyRow,'restore preserves the original archive event byte-for-byte');
for($i=0;$i<12;$i++)$state=$archive->save($id,!$state['archived'],$state['version']);
check($archive->history($id)['total']===14&&count($archive->history($id)['rows'])===10&&count($archive->history($id,2)['rows'])===4,'full original archive history is bounded to ten records per page');
$ui=new MediaLibrary($db,$admin,$root.'/media','own-token');
denied(fn()=>$ui->action(['csrf'=>'wrong','operation'=>'media-archive-save','id'=>$id,'archive_version'=>(string)$state['version'],'archived'=>'1'],[]),'actual archive controller retains CSRF');
foreach([[],true,'yes',2]as$bad)denied(fn()=>$ui->action(['csrf'=>'own-token','operation'=>'media-archive-save','id'=>$id,'archive_version'=>(string)$state['version'],'archived'=>$bad],[]),'actual archive controller rejects malformed state');
$result=$ui->action(['csrf'=>'own-token','operation'=>'media-archive-save','id'=>$id,'archive_version'=>(string)$state['version'],'archived'=>'1'],[]);check($result['item']===$id&&$result['notice']==='Bild archiviert.','actual controller returns the same original photo');
check(str_contains($ui->manager($id),'Bild zurückholen')&&str_contains($ui->manager($id),'Archivverlauf'),'actual editor offers reversible archival and bounded history');
check(!str_contains((new MediaLibrary($db,$reader,$root.'/media','own-token'))->manager($id),'value="media-archive-save"'),'reader has no archive write form');
check(str_contains($ui->manager('',['media_archive'=>'archived']),'Archiviert'),'actual archived catalogue labels the separate lifecycle state');
check($originals===[$db->query('SELECT * FROM khcms_media ORDER BY id')->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata ORDER BY media_id')->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata_revisions ORDER BY media_id,version')->fetchAll(),$db->query('SELECT * FROM khcms_pages ORDER BY id')->fetchAll(),$db->query('SELECT * FROM khcms_revisions ORDER BY page_id,revision')->fetchAll()],'every original upload, copyright revision and published draft row stays byte-identical');
foreach($hashes as$size=>$hash)check(hash_file('sha256',$media->variant($id,$size)['path'])===$hash,'original '.$size.' photo pixels remain byte-identical');
echo $checks." reversible media archive checks passed; original source pixels and approvals retained, no transport.\n";
